import os
from typing import Any, Dict, List, Literal, Optional

import assemblyai as aai


TimestampLevel = Literal["word", "segment"]


def transcribe_with_timestamps(
    audio_path: str,
    level: TimestampLevel = "word",
    language_code: Optional[str] = None,
) -> List[Dict[str, Any]]:
    api_key = os.environ["ASSEMBLYAI_API_KEY"]
    aai.settings.api_key = api_key

    config = aai.TranscriptionConfig(
        speech_model=aai.SpeechModel.best,
        language_code=language_code,
    )

    transcriber = aai.Transcriber()
    transcript = transcriber.transcribe(audio_path, config=config)

    if transcript.status == aai.TranscriptStatus.error:
        raise RuntimeError(transcript.error)

    if level == "word":
        return [
            {
                "text": word.text,
                "start_ms": word.start,
                "end_ms": word.end,
                "confidence": getattr(word, "confidence", None),
            }
            for word in (transcript.words or [])
        ]

    if level == "segment":
        return [
            {
                "text": utterance.text,
                "start_ms": utterance.start,
                "end_ms": utterance.end,
                "confidence": getattr(utterance, "confidence", None),
                "speaker": getattr(utterance, "speaker", None),
            }
            for utterance in (transcript.utterances or [])
        ] or [
            {
                "text": transcript.text,
                "start_ms": 0,
                "end_ms": max((w.end for w in (transcript.words or [])), default=0),
                "confidence": None,
                "speaker": None,
            }
        ]

    raise ValueError("level must be 'word' or 'segment'")
